tools.example:
fun = @(x) 100*(x(2)-x(1)^2)^2 + (1-x(1))^2;
nonlcon = @(x) deal(x(1)^2 + x(2)^2 - 1.5, []);   % c <= 0, no ceq
opts = optimoptions('fmincon', 'Algorithm', 'sqp', 'Display', 'iter');
[x, fval, exitflag] = fmincon(fun, [0.5 0.5], [], [], [], [], ...
    [-2 -2], [2 2], nonlcon, opts);
fprintf('x = [%.4f %.4f], f = %.6f\n', x, fval);

fun = @(x) deal(100*(x(2)-x(1)^2)^2 + (1-x(1))^2, ...
    [-400*x(1)*(x(2)-x(1)^2) - 2*(1-x(1)); 200*(x(2)-x(1)^2)]);
opts = optimoptions('fminunc', 'Algorithm', 'trust-region', ...
    'SpecifyObjectiveGradient', true, 'Display', 'iter');
[x, fval] = fminunc(fun, [-1.2; 1], opts);

fun = @(x) abs(x(1)-3) + abs(x(2)+2) + 0.1*randn;
opts = optimset('TolX', 1e-6, 'MaxIter', 2000, 'Display', 'off');
[x, fval] = fminsearch(fun, [0 0], opts);
fprintf('x = [%.3f %.3f]\n', x);

% maximize 5x + 4y  ->  minimize -5x - 4y
f = [-5; -4];
A = [6 4; 1 2];
b = [24; 6];
lb = [0; 0];
[x, fval, exitflag] = linprog(f, A, b, [], [], lb, []);
fprintf('x = %.2f, y = %.2f, profit = %.2f\n', x(1), x(2), -fval);

% 0-1 knapsack: maximize value subject to weight <= 15
value  = [10 13 18 31 7 15];
weight = [ 3  4  5  9 2  4];
f = -value';
intcon = 1:6;
A = weight; b = 15;
lb = zeros(6,1); ub = ones(6,1);
opts = optimoptions('intlinprog', 'Display', 'off');
[x, fval] = intlinprog(f, intcon, A, b, [], [], lb, ub, opts);
fprintf('Total value %.0f, items: %s\n', -fval, mat2str(find(round(x))'));

% Minimum-variance portfolio with target return
Sigma = [0.04 0.006 0.002; 0.006 0.09 0.012; 0.002 0.012 0.0225];
mu = [0.08; 0.12; 0.10];
H = 2*Sigma; f = zeros(3,1);
Aeq = [ones(1,3); mu'];  beq = [1; 0.10];
lb = zeros(3,1);
[w, v] = quadprog(H, f, [], [], Aeq, beq, lb, []);
fprintf('Weights: %s, variance %.5f\n', mat2str(round(w,4)'), v/2);

t = (0:0.1:5)';
ydata = 3*exp(-1.3*t) + 0.5 + 0.02*randn(size(t));
fun = @(p) p(1)*exp(-p(2)*t) + p(3) - ydata;
[p, resnorm, residual, exitflag] = lsqnonlin(fun, [1 1 0], [0 0 -1], [10 5 2]);
fprintf('a=%.3f b=%.3f c=%.3f, SSE=%.4g\n', p, resnorm);

xdata = linspace(0, 3, 50)';
ydata = 5*exp(-1.2*xdata) .* sin(4*xdata) + 0.05*randn(50,1);
fun = @(p, x) p(1)*exp(-p(2)*x) .* sin(p(3)*x);
opts = optimoptions('lsqcurvefit', 'Display', 'off');
[p, resnorm] = lsqcurvefit(fun, [4 1 3], xdata, ydata, [0 0 0], [20 10 20], opts);
plot(xdata, ydata, 'o', xdata, fun(p, xdata), '-')

rng(0)
C = randn(50, 4);
d = C * [0.3; 0.2; 0.4; 0.1] + 0.01*randn(50,1);
Aeq = ones(1,4); beq = 1;     % coefficients sum to 1
lb = zeros(4,1);              % and are nonnegative
[x, resnorm] = lsqlin(C, d, [], [], Aeq, beq, lb, []);
disp(round(x, 4)')

F = @(x) [2*x(1) - x(2) - exp(-x(1));
         -x(1) + 2*x(2) - exp(-x(2))];
opts = optimoptions('fsolve', 'Display', 'off', 'Algorithm', 'levenberg-marquardt');
[x, fval, exitflag] = fsolve(F, [-5; -5], opts);
fprintf('Solution [%.5f %.5f], |F| = %.2e\n', x, norm(fval));

A = [-0.5 0 0; 0 -2 10; 0 1 -2];
B = [1 0; -2 2; 0 1];
C = [1 0 0; 0 0 1];
fun = @(K) sort(real(eig(A + B*K*C)));
goal = [-5 -3 -1];
weight = abs(goal);
[K, fval, attainfactor] = fgoalattain(fun, -ones(2,2), goal, weight);
fprintf('Attainment factor: %.4f\n', attainfactor);

tools.usage:
prob = optimproblem
prob = optimproblem(Name, Value)
prob.Objective = expr;
prob.Constraints.name = constraintExpr;

tools.example:
prob = optimproblem('ObjectiveSense', 'maximize');
x = optimvar('x', 2, 'LowerBound', 0);
prob.Objective = 5*x(1) + 4*x(2);
prob.Constraints.c1 = 6*x(1) + 4*x(2) <= 24;
prob.Constraints.c2 = x(1) + 2*x(2) <= 6;
show(prob)
[sol, fval] = solve(prob);
disp(sol.x)

plants = {'A','B'};
markets = {'X','Y','Z'};
ship = optimvar('ship', plants, markets, 'LowerBound', 0);
prob = optimproblem;
cost = [4 6 9; 5 3 8];
prob.Objective = sum(sum(cost .* ship));
prob.Constraints.supply = sum(ship, 2) <= [100; 120];
prob.Constraints.demand = sum(ship, 1) >= [60 70 80];
sol = solve(prob);
disp(sol.ship)

prob = optimproblem;
x = optimvar('x', 'LowerBound', -5, 'UpperBound', 5);
y = optimvar('y', 'LowerBound', -5, 'UpperBound', 5);
prob.Objective = (1-x)^2 + 100*(y - x^2)^2;
x0.x = 0; x0.y = 0;
[sol, fval, exitflag] = solve(prob, x0, 'Options', optimoptions('fmincon','Display','off'));
fprintf('x = %.4f, y = %.4f, f = %.3e\n', sol.x, sol.y, fval);

prob = optimproblem('ObjectiveSense', 'maximize');
x = optimvar('x', 2, 'LowerBound', 0);
prob.Objective = 5*x(1) + 4*x(2);
prob.Constraints.c1 = 6*x(1) + 4*x(2) <= 24;
s = prob2struct(prob);
disp(s.f')      % note: negated because linprog minimizes
disp(s.Aineq)

rng(0)
fun = @(x) 20 + sum(x.^2 - 10*cos(2*pi*x));   % Rastrigin
opts = optimoptions('ga', 'PopulationSize', 200, 'MaxGenerations', 300, ...
    'HybridFcn', @fmincon, 'Display', 'off', 'PlotFcn', @gaplotbestf);
[x, fval, exitflag] = ga(fun, 2, [], [], [], [], [-5.12 -5.12], [5.12 5.12], [], opts);
fprintf('x = [%.4f %.4f], f = %.6f\n', x, fval);

rng(1)
fun = @(x) [x(1)^2 + x(2)^2; (x(1)-2)^2 + (x(2)-1)^2];
opts = optimoptions('gamultiobj', 'PopulationSize', 120, ...
    'ParetoFraction', 0.5, 'Display', 'off');
[x, fval] = gamultiobj(fun, 2, [], [], [], [], [-4 -4], [4 4], opts);
plot(fval(:,1), fval(:,2), 'o')
xlabel('f_1'), ylabel('f_2'), title('Pareto front')

rng(0)
fun = @(x) sum(100*(x(2:end) - x(1:end-1).^2).^2 + (1 - x(1:end-1)).^2);
opts = optimoptions('particleswarm', 'SwarmSize', 100, ...
    'HybridFcn', @fminunc, 'Display', 'off');
[x, fval] = particleswarm(fun, 5, -5*ones(1,5), 5*ones(1,5), opts);
fprintf('f = %.3e\n', fval);

rng(0)
fun = @(x) 20 + sum(x.^2 - 10*cos(2*pi*x));
opts = optimoptions('simulannealbnd', 'InitialTemperature', 200, ...
    'HybridFcn', @fmincon, 'Display', 'off');
[x, fval] = simulannealbnd(fun, [3 3], [-5.12 -5.12], [5.12 5.12], opts);
fprintf('f = %.6f at [%.4f %.4f]\n', fval, x);

fun = @(x) abs(x(1)) + abs(x(2)) + 10*abs(x(1)*x(2) - 1);
opts = optimoptions('patternsearch', 'UseCompletePoll', true, ...
    'PollMethod', 'MADSPositiveBasis2N', 'Display', 'off');
[x, fval] = patternsearch(fun, [2 2], [], [], [], [], [-5 -5], [5 5], [], opts);
fprintf('x = [%.4f %.4f], f = %.6f\n', x, fval);

rng(0)
objconstr = @(x) struct('Fval', 20 + sum(x.^2 - 10*cos(2*pi*x)));
opts = optimoptions('surrogateopt', 'MaxFunctionEvaluations', 200, 'Display', 'off');
[x, fval, exitflag] = surrogateopt(objconstr, [-5.12 -5.12], [5.12 5.12], opts);
fprintf('f = %.5f\n', fval);

rng(0)
fun = @(x) 20 + sum(x.^2 - 10*cos(2*pi*x));
problem = createOptimProblem('fmincon', 'objective', fun, ...
    'x0', [2 2], 'lb', [-5.12 -5.12], 'ub', [5.12 5.12], ...
    'options', optimoptions('fmincon','Display','off'));
gs = GlobalSearch('NumTrialPoints', 2000, 'Display', 'off');
[x, fval, exitflag, output, solutions] = run(gs, problem);
fprintf('Best f = %.6f from %d distinct minima\n', fval, numel(solutions));

rng(0)
fun = @(p) p(1)*exp(-p(2)*(0:0.1:5)') - (3*exp(-1.3*(0:0.1:5)') + 0.01*randn(51,1));
problem = createOptimProblem('lsqnonlin', 'objective', fun, ...
    'x0', [1 1], 'lb', [0 0], 'ub', [10 5]);
ms = MultiStart('UseParallel', false, 'Display', 'off');
[x, fval, ~, ~, solutions] = run(ms, problem, 30);
fprintf('Best residual %.4g, %d local minima\n', fval, numel(solutions));

problem = createOptimProblem('fmincon', ...
    'objective', @(x) x(1)^2 + x(2)^2 + 3*sin(5*x(1)), ...
    'x0', [1 1], 'lb', [-3 -3], 'ub', [3 3], ...
    'options', optimoptions('fmincon', 'Algorithm', 'sqp', 'Display', 'off'));
gs = GlobalSearch('Display', 'off');
[x, fval] = run(gs, problem);

rng(0)
fun = @(x) [norm(x - [1 1])^2; norm(x + [1 1])^2];
opts = optimoptions('paretosearch', 'ParetoSetSize', 80, 'Display', 'off');
[x, fval] = paretosearch(fun, 2, [], [], [], [], [-3 -3], [3 3], [], opts);
plot(fval(:,1), fval(:,2), '.')

load ionosphere
